import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Quick feature selection based on t-statistics
    t_stats = []
    for fid in feats.ids:
        col_idx = feats.column(fid)
        # Only consider non-clinical features for quick filtering
        if feats.types[col_idx] != 'clinical':
            try:
                t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, col_idx], 
                                           feats.x[feats.y==0, col_idx])[0])
                t_stats.append((fid, t_stat))
            except:
                continue

    # Sort by t-statistic and take top candidates
    t_stats.sort(key=lambda x: x[1], reverse=True)
    top_candidates = [fid for fid, _ in t_stats[:15]]  # Limit to top 15

    # Quick correlation check to remove near-duplicates
    selected_ids = []
    for fid in top_candidates:
        is_duplicate = False
        col_idx = feats.column(fid)
        for selected_fid in selected_ids:
            selected_col = feats.column(selected_fid)
            try:
                corr = np.corrcoef(feats.x[:, col_idx], feats.x[:, selected_col])[0,1]
                if abs(corr) >= 0.6:
                    is_duplicate = True
                    break
            except:
                continue
        if not is_duplicate:
            selected_ids.append(fid)
        if len(selected_ids) >= MAX_DRIVERS:
            break

    # Drivers are top features
    drivers = tuple(selected_ids)

    # All selected features for columns
    columns = tuple(selected_ids)

    # Simple interaction terms between top features
    products = []
    for i in range(min(3, len(selected_ids))):
        for j in range(i+1, min(3, len(selected_ids))):
            products.append((selected_ids[i], selected_ids[j]))

    # Loadings based on correlation with outcome
    loadings = {}
    for fid in selected_ids:
        col_idx = feats.column(fid)
        try:
            corr = np.corrcoef(feats.x[:, col_idx], feats.y)[0,1]
            loadings[fid] = abs(corr)
        except:
            loadings[fid] = 0.0

    # Normalize loadings
    total = sum(loadings.values())
    if total > 0:
        for k in loadings:
            loadings[k] /= total

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

